function nearest(range){let a=mobs.filter(m=>m.hp>0&&distance(S,m)<range).sort((a,b)=>distance(S,a)-distance(S,b));return selectedEnemy&&a.includes(selectedEnemy)?selectedEnemy:a[0]}
